fn apply_simple_cors_headers(cors: &CorsConfig, origin: &HeaderValue, headers: &mut HeaderMap) {
    let Some((allow_origin, needs_vary)) = resolve_allow_origin(cors, origin) else {
        return;
    };
    headers.insert(ACCESS_CONTROL_ALLOW_ORIGIN, allow_origin);
    if needs_vary {
        headers.insert(VARY, HeaderValue::from_static("origin"));
    }
    if cors.allow_credentials {
        headers.insert(
            ACCESS_CONTROL_ALLOW_CREDENTIALS,
            HeaderValue::from_static("true"),
        );
    }
}

/// Build the response returned for a CORS preflight (`OPTIONS`) request.
fn build_preflight_response(
    cors: &CorsConfig,
    origin: &HeaderValue,
    request_headers: &HeaderMap,
) -> Response {
    let mut response = Response::new(Body::empty());
    *response.status_mut() = StatusCode::OK;
    let headers = response.headers_mut();

    if let Some((allow_origin, needs_vary)) = resolve_allow_origin(cors, origin) {
        headers.insert(ACCESS_CONTROL_ALLOW_ORIGIN, allow_origin);
        if needs_vary {
            headers.insert(VARY, HeaderValue::from_static("origin"));
        }
    }

    if let Ok(methods) = HeaderValue::from_str(&resolve_allow_methods(cors)) {
        headers.insert(ACCESS_CONTROL_ALLOW_METHODS, methods);
    }

    if let Some(allow_headers) = resolve_allow_headers(cors, request_headers) {
        headers.insert(ACCESS_CONTROL_ALLOW_HEADERS, allow_headers);
    }

    if cors.allow_credentials {
        headers.insert(
            ACCESS_CONTROL_ALLOW_CREDENTIALS,
            HeaderValue::from_static("true"),
        );
    }

    response
}

/// Resolve the comma-separated method list advertised in preflight responses,
/// expanding the wildcard `*` to the explicit set of standard HTTP verbs.
fn resolve_allow_methods(cors: &CorsConfig) -> String {
    if cors.allow_methods.iter().any(|method| method == "*") {
        ALL_METHODS.join(",")
    } else {
        cors.allow_methods.join(",")
    }
}

/// Resolve the `Access-Control-Allow-Headers` value for a preflight request.
///
/// A wildcard header list mirrors the client's `Access-Control-Request-Headers`
/// verbatim. An explicit list is unioned with the CORS safelist and returned in
/// a lowercased, sorted form.
fn resolve_allow_headers(cors: &CorsConfig, request_headers: &HeaderMap) -> Option<HeaderValue> {
    if cors.allow_headers.iter().any(|header| header == "*") {
        request_headers.get(ACCESS_CONTROL_REQUEST_HEADERS).cloned()
    } else {
        let mut headers: BTreeSet<String> =
            SAFELISTED_HEADERS.iter().map(|header| header.to_string()).collect();
        for header in &cors.allow_headers {
            headers.insert(header.to_ascii_lowercase());
        }
        HeaderValue::from_str(&headers.into_iter().collect::<Vec<_>>().join(",")).ok()
    }
}
